import type { Vec2 } from '../core/types';

export type GeneratedHairRole='hair'|'hairTie';
export type GeneratedEyeRole='pupil'|'white'|'eyes';
export interface GeneratedVariantTriangle<R extends string>{role:R;points:readonly [Vec2,Vec2,Vec2];shade:number}

export const GENERATED_VARIATION_SOURCE={
  kind:'generated-reference-sheet',
  hairCount:10,eyeCount:10,
  hairScale:0.011600,eyeScale:0.006100,
  method:'rgb/lab-segmentation+feature-points+delaunay+contour-hulls',
} as const;

const HAIR_ROLES:readonly GeneratedHairRole[]=['hair','hairTie'];
const EYE_ROLES:readonly GeneratedEyeRole[]=['pupil','white','eyes'];
const decode=<R extends string>(b64:string,roles:readonly R[]):GeneratedVariantTriangle<R>[]=>{
  const raw=atob(b64),bytes=Uint8Array.from(raw,c=>c.charCodeAt(0)),view=new DataView(bytes.buffer,bytes.byteOffset,bytes.byteLength),out:GeneratedVariantTriangle<R>[]=[];
  for(let o=0;o+13<bytes.byteLength;o+=14){
    const p=(i:number):Vec2=>[view.getInt16(o+i,true)/10000,view.getInt16(o+i+2,true)/10000];
    out.push({points:[p(0),p(4),p(8)],shade:view.getInt8(o+12),role:roles[view.getUint8(o+13)]});
  }
  return out;
};

